package kr.minecraft.survival.economy;

import java.lang.reflect.Proxy;
import java.util.*;
import net.milkbowl.vault.economy.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.ServicePriority;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.mockbukkit.mockbukkit.*;
import org.mockbukkit.mockbukkit.entity.PlayerMock;
import kr.minecraft.survival.economy.domain.*;

class TycoonIntegrationTest {
    ServerMock server;KoreanEconomyPlugin plugin;SavedPlayer player;Tycoon t;final Map<UUID,Double> balances=new HashMap<>();
    /** MockBukkit does not implement player NBT saves. Other Bukkit behavior stays in real MockBukkit. */
    static class SavedPlayer extends PlayerMock {int saves;SavedPlayer(ServerMock s,String name){super(s,name);} @Override public void saveData(){saves++;}}
    @BeforeEach void start(){
        server=MockBukkit.mock();server.addSimpleWorld("world");var vault=MockBukkit.createMockPlugin("Vault");
        Economy provider=(Economy)Proxy.newProxyInstance(Economy.class.getClassLoader(),new Class[]{Economy.class},(o,m,a)->{
            String n=m.getName();UUID id=a!=null&&a.length>0&&a[0] instanceof OfflinePlayer p?p.getUniqueId():null;
            if(n.equals("has"))return balances.getOrDefault(id,0.0)>=(double)a[a.length-1];
            if(n.equals("getBalance"))return balances.getOrDefault(id,0.0);
            if(n.equals("depositPlayer")||n.equals("withdrawPlayer")){double amount=(double)a[a.length-1],old=balances.getOrDefault(id,0.0);if(n.equals("withdrawPlayer")&&old<amount)return new EconomyResponse(0,old,EconomyResponse.ResponseType.FAILURE,"funds");double next=old+(n.equals("depositPlayer")?amount:-amount);balances.put(id,next);return new EconomyResponse(amount,next,EconomyResponse.ResponseType.SUCCESS,"");}
            if(m.getReturnType()==boolean.class)return true;if(m.getReturnType()==int.class)return 2;if(m.getReturnType()==double.class)return 0.0;if(n.equals("toString"))return "TestWallet";return null;
        });server.getServicesManager().register(Economy.class,provider,vault,ServicePriority.Normal);
        plugin=MockBukkit.load(KoreanEconomyPlugin.class);assertTrue(plugin.isEnabled());t=plugin.tycoon;
        player=new SavedPlayer(server,"Farmer");server.addPlayer(player);player.setGameMode(GameMode.SURVIVAL);balances.put(player.getUniqueId(),100000.0);t.register(player);
    }
    @AfterEach void stop(){MockBukkit.unmock();}
    void choose(Rules.Job job){t.store.transaction(()->{t.store.selectJobInside(player.getUniqueId(),job,System.currentTimeMillis());return null;});}
    void click(int slot){var view=player.getOpenInventory();var event=new InventoryClickEvent(view,InventoryType.SlotType.CONTAINER,slot,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(event);assertTrue(event.isCancelled());server.getScheduler().performTicks(2);}
    @Test void dailyPaysOnceAcrossFreshMenuCalls(){double before=balances.get(player.getUniqueId());t.daily(player,20000);t.daily(player,20000);assertEquals(before+200,balances.get(player.getUniqueId()));assertTrue(t.store.paid(player.getUniqueId(),"daily:"+t.day()));}
    @Test void cookingConsumesOnlyPlainIngredientsAndProducesIdentifiedDish(){choose(Rules.Job.FARMER);player.getInventory().setItem(0,new ItemStack(Material.WHEAT,6));t.cook(player,Rules.recipe("mill_bread"));assertEquals(3,player.getInventory().getItem(0).getAmount());assertTrue(Arrays.stream(player.getInventory().getStorageContents()).filter(Objects::nonNull).anyMatch(i->i.isSimilar(t.dish(Rules.recipe("mill_bread")))));assertEquals(1,player.saves);}
    @Test void namedIngredientsAndFullInventoryNeverDisappear(){choose(Rules.Job.FARMER);ItemStack named=Tycoon.icon(Material.WHEAT,"기념품");named.setAmount(3);player.getInventory().setItem(0,named);ItemStack[] before=ItemPlans.copy(player.getInventory().getStorageContents());assertThrows(StateStore.Denied.class,()->t.cook(player,Rules.recipe("mill_bread")));assertArrayEquals(before,player.getInventory().getStorageContents());}
    @Test void unstackableSoupUsesSeparateSlots(){ItemStack[] result=ItemPlans.move(new ItemStack[3],t.dish(Rules.recipe("mushroom_soup")),3,true);assertNotNull(result);for(ItemStack i:result)assertEquals(1,i.getAmount());assertNull(ItemPlans.move(new ItemStack[2],t.dish(Rules.recipe("mushroom_soup")),3,true));}
    @Test void levelingUnlocksCookingAndKeepsProgressOnJobSwitch(){choose(Rules.Job.FARMER);assertThrows(StateStore.Denied.class,()->t.cook(player,Rules.recipe("pumpkin_pie")));t.store.grantXp(player.getUniqueId(),Rules.Job.FARMER,300,t.day(),1000);choose(Rules.Job.MINER);choose(Rules.Job.FARMER);assertEquals(3,t.store.progress(player.getUniqueId(),Rules.Job.FARMER).level());}
    @Test void questDeliveryIsAtomicAndCannotPayTwice(){Rules.Quest q=Rules.quest("deliver_wheat");t.store.acceptQuest(player.getUniqueId(),t.day(),q.id(),3);player.getInventory().setItem(0,new ItemStack(Material.WHEAT,32));double before=balances.get(player.getUniqueId());t.quests(player,null);click(19);assertEquals(before+120,balances.get(player.getUniqueId()));assertTrue(player.getInventory().isEmpty());t.quests(player,null);click(19);assertEquals(before+120,balances.get(player.getUniqueId()));}
    @Test void menuRejectsBottomShiftAndNumberKeyActions(){t.jobs(player);var view=player.getOpenInventory();var e=new InventoryClickEvent(view,InventoryType.SlotType.CONTAINER,54,ClickType.SHIFT_LEFT,InventoryAction.MOVE_TO_OTHER_INVENTORY);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());server.getScheduler().performTicks(2);assertNull(t.store.job(player.getUniqueId()));}
    @Test void upgradeStaleToolCannotChargeOrReplace(){player.getInventory().setItemInMainHand(new ItemStack(Material.IRON_PICKAXE));t.upgradeMenu(player);player.getInventory().setItemInMainHand(new ItemStack(Material.DIAMOND_PICKAXE));double before=balances.get(player.getUniqueId());click(31);assertEquals(before,balances.get(player.getUniqueId()));assertEquals(Material.DIAMOND_PICKAXE,player.getInventory().getItemInMainHand().getType());}
    @Test void firstUpgradeAlwaysSucceedsAndPersistsMetadata(){player.getInventory().setItemInMainHand(new ItemStack(Material.IRON_PICKAXE));double before=balances.get(player.getUniqueId());t.upgradeMenu(player);click(31);assertEquals(before-1000,balances.get(player.getUniqueId()));assertEquals(1,player.getInventory().getItemInMainHand().getItemMeta().getPersistentDataContainer().get(t.upgradeKey,org.bukkit.persistence.PersistentDataType.INTEGER));}
    @Test void claimedLandProtectsStrangersButTrustCanBeRevoked(){t.lands.command(player,new String[]{"생성","확인"});var other=new SavedPlayer(server,"Other");server.addPlayer(other);t.register(other);var block=player.getLocation().getBlock();block.setType(Material.STONE);var e=new BlockBreakEvent(block,other);server.getPluginManager().callEvent(e);assertTrue(e.isCancelled());t.lands.command(player,new String[]{"초대","Other"});assertTrue(t.lands.allowed(other,block.getLocation()));t.lands.command(player,new String[]{"추방","Other"});assertFalse(t.lands.allowed(other,block.getLocation()));}
    @Test void claimExpansionChargesAndRejectsDistantClaims(){double before=balances.get(player.getUniqueId());t.lands.command(player,new String[]{"생성","확인"});assertEquals(before,balances.get(player.getUniqueId()));player.teleport(new Location(player.getWorld(),16,64,0));t.lands.command(player,new String[]{"확장","확인"});assertEquals(before-2500,balances.get(player.getUniqueId()));player.teleport(new Location(player.getWorld(),80,64,0));assertThrows(StateStore.Denied.class,()->t.lands.command(player,new String[]{"확장","확인"}));assertEquals(before-2500,balances.get(player.getUniqueId()));}
    @Test void realNativeVillagerNpcOpensFoodMenuAndPersistsOwnTag(){
        var npc=player.getWorld().spawnEntity(player.getLocation(),org.bukkit.entity.EntityType.VILLAGER);
        npc.getPersistentDataContainer().set(new NamespacedKey(plugin,"market_npc"),org.bukkit.persistence.PersistentDataType.STRING,"FOOD");
        assertEquals(ShopCategory.FOOD,plugin.npcs.category(npc));
        var event=new org.bukkit.event.player.PlayerInteractEntityEvent(player,npc,EquipmentSlot.HAND);server.getPluginManager().callEvent(event);assertTrue(event.isCancelled());server.getScheduler().performTicks(2);assertTrue(player.getOpenInventory().getTopInventory().getHolder() instanceof Tycoon.Screen);
        assertFalse(plugin.npcs.nearby(player,player.getWorld().spawnEntity(new Location(player.getWorld(),100,64,0),org.bukkit.entity.EntityType.VILLAGER)));
    }
    @Test void merchantPaysOnlyForCanonicalDish(){Rules.Recipe recipe=Rules.recipe("mill_bread");player.getInventory().setItem(0,new ItemStack(Material.BREAD));double before=balances.get(player.getUniqueId());t.foodShop(player,null);click(10);assertEquals(before,balances.get(player.getUniqueId()));assertEquals(Material.BREAD,player.getInventory().getItem(0).getType());}
    @Test void foodSaleUsesPersonalDailyQuota(){Rules.Recipe r=Rules.recipe("mill_bread");player.getInventory().setItem(0,t.dish(r));t.store.execute("INSERT INTO daily_use(uuid,day,product,quantity) VALUES(?,?,?,?)",player.getUniqueId(),t.day(),"food:"+r.id(),r.dailyLimit());double before=balances.get(player.getUniqueId());t.foodShop(player,null);click(10);assertEquals(before,balances.get(player.getUniqueId()));assertNotNull(player.getInventory().getItem(0));}
    @Test void revokedTrustBlocksAnAlreadyOpenInventoryClick(){t.lands.command(player,new String[]{"생성","확인"});SavedPlayer other=new SavedPlayer(server,"Friend");server.addPlayer(other);t.register(other);t.lands.command(player,new String[]{"초대","Friend"});var block=player.getLocation().getBlock();block.setType(Material.CHEST);var chest=(org.bukkit.block.Chest)block.getState();other.openInventory(chest.getInventory());t.lands.command(player,new String[]{"추방","Friend"});var event=new InventoryClickEvent(other.getOpenInventory(),InventoryType.SlotType.CONTAINER,0,ClickType.LEFT,InventoryAction.PICKUP_ALL);server.getPluginManager().callEvent(event);assertTrue(event.isCancelled());}
    @Test void auditDoesNotRollbackContainersAndSkipsChangedBlocks(){var block=player.getLocation().getBlock();block.setType(Material.STONE);long since=System.currentTimeMillis();t.audit.append(player.getUniqueId().toString(),block.getLocation(),"BLOCK","minecraft:dirt".getBytes(),"minecraft:stone".getBytes(),"test");var rows=t.store.audit(player.getWorld().getUID().toString(),since-1000,block.getX(),block.getZ(),1,null,10);assertEquals(1,rows.size());assertTrue(AuditLog.isTileMaterial(Material.CHEST));assertTrue(AuditLog.isTileMaterial(Material.SHULKER_BOX));assertFalse(AuditLog.isTileMaterial(Material.STONE));}
    @Test void rawShopRefusesInsufficientFundsWithoutGivingItems(){balances.put(player.getUniqueId(),0.0);plugin.open(player,true,ShopCategory.ALL,null);click(19);assertTrue(player.getInventory().isEmpty());assertEquals(0.0,balances.get(player.getUniqueId()));}
    @Test void rawShopSalePaysAndConsumesPlainStack(){player.getInventory().setItem(0,new ItemStack(Material.WHEAT,2));double before=balances.get(player.getUniqueId());plugin.open(player,false,ShopCategory.CROPS,null);click(19);assertEquals(before+2,balances.get(player.getUniqueId()));assertEquals(1,player.getInventory().getItem(0).getAmount());assertEquals(1,t.store.used(player.getUniqueId(),t.day(),"raw:WHEAT"));}
    String previewToken(){String token=null;for(String message;(message=player.nextMessage())!=null;){var matcher=java.util.regex.Pattern.compile("/생활기록 복구 ([a-f0-9]{8})").matcher(message);if(matcher.find())token=matcher.group(1);}assertNotNull(token);return token;}
    @Test void operatorRollbackRestoresOrdinaryBlockButRejectsLaterConflict(){player.setOp(true);var b=player.getLocation().getBlock();b.getWorld().loadChunk(b.getX()>>4,b.getZ()>>4);b.setType(Material.STONE);t.audit.append(player.getUniqueId().toString(),b.getLocation(),"BLOCK","minecraft:dirt".getBytes(),"minecraft:stone".getBytes(),"test");t.audit.command(player,new String[]{"미리보기","1","10"});String token=previewToken();t.audit.command(player,new String[]{"복구",token});assertEquals(Material.DIRT,b.getType());
        b.setType(Material.STONE);t.audit.append(player.getUniqueId().toString(),b.getLocation(),"BLOCK","minecraft:dirt".getBytes(),"minecraft:stone".getBytes(),"test");t.audit.command(player,new String[]{"미리보기","1","10"});token=previewToken();b.setType(Material.DIAMOND_BLOCK);t.audit.command(player,new String[]{"복구",token});assertEquals(Material.DIAMOND_BLOCK,b.getType());}
    @Test void hopperCannotTransferAcrossUntrustedClaimBoundary(){t.lands.command(player,new String[]{"생성","확인"});var w=player.getWorld();var inside=w.getBlockAt(15,64,0);var outside=w.getBlockAt(16,64,0);inside.setType(Material.HOPPER);outside.setType(Material.CHEST);var source=((org.bukkit.block.Hopper)inside.getState()).getInventory();var dest=((org.bukkit.block.Chest)outside.getState()).getInventory();var event=new InventoryMoveItemEvent(source,new ItemStack(Material.DIAMOND),dest,true);server.getPluginManager().callEvent(event);assertTrue(event.isCancelled());}
    @Test void oldDishesRemainSellableAfterResourcePackSettingChanges(){Rules.Recipe r=Rules.recipe("mill_bread");player.getInventory().setItem(0,t.dish(r,false));plugin.getConfig().set("리소스팩-사용",true);double before=balances.get(player.getUniqueId());t.sellFood(player,r,1);assertEquals(before+12,balances.get(player.getUniqueId()));assertTrue(player.getInventory().isEmpty());}
    @Test void mixedCanonicalModelsSellTogetherInOneTransaction(){Rules.Recipe r=Rules.recipe("mill_bread");player.getInventory().setItem(0,t.dish(r,false));player.getInventory().setItem(1,t.dish(r,true));double before=balances.get(player.getUniqueId());t.sellFood(player,r,2);assertEquals(before+24,balances.get(player.getUniqueId()));assertTrue(player.getInventory().isEmpty());}
    @Test void townCreatesFiveNativeNpcsWithoutReplacingBlocks(){player.setOp(true);player.teleport(new Location(player.getWorld(),0.5,64,0.5));for(int x=-5;x<=5;x++)for(int z=0;z<=4;z++){player.getWorld().getBlockAt(x,63,z).setType(Material.STONE);player.getWorld().getBlockAt(x,64,z).setType(Material.AIR);player.getWorld().getBlockAt(x,65,z).setType(Material.AIR);}plugin.npcs.town(player,new String[]{"확인"});long count=player.getWorld().getEntities().stream().filter(e->plugin.npcs.category(e)!=null).count();assertEquals(5,count);assertEquals(Material.STONE,player.getWorld().getBlockAt(2,63,2).getType());}
    @Test void shiftFMenuOpensJobsWithoutGrantingOperator(){
        var description=java.nio.file.Path.of(System.getProperty("tycoon.repo"),"korean-menu/src/main/resources/plugin.yml").toFile();
        MockBukkit.loadWith(kr.minecraft.survival.menu.KoreanMenuPlugin.class,description);player.recalculatePermissions();player.setSneaking(true);assertTrue(player.hasPermission("koreanmenu.use"),"default menu permission");
        var event=new org.bukkit.event.player.PlayerSwapHandItemsEvent(player,new ItemStack(Material.AIR),new ItemStack(Material.AIR));server.getPluginManager().callEvent(event);assertTrue(event.isCancelled(),"shift F event cancelled");server.getScheduler().performTicks(2);assertTrue(player.getOpenInventory().getTitle().contains("마을 수첩"),"main menu opened");click(37);server.getScheduler().performTicks(2);assertTrue(player.getOpenInventory().getTopInventory().getHolder() instanceof Tycoon.Screen,"job menu opened");assertFalse(player.isOp());
    }
    @Test void onlineBackupContainsVerifiedConsistentSqliteSnapshot() throws Exception {
        t.backups.start(null);java.nio.file.Path folder=plugin.getDataFolder().toPath().resolve("백업"),found=null;long deadline=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(10);
        while(found==null&&System.nanoTime()<deadline){if(java.nio.file.Files.exists(folder))try(var files=java.nio.file.Files.list(folder)){found=files.filter(f->f.toString().endsWith(".zip")).findFirst().orElse(null);}if(found==null)Thread.sleep(10);}
        assertNotNull(found);try(var zip=new java.util.zip.ZipFile(found.toFile())){assertNotNull(zip.getEntry("생활경제.db"));assertNotNull(zip.getEntry("SHA256.properties"));java.nio.file.Path copy=java.nio.file.Files.createTempFile("tycoon-backup-test-",".db");try{try(var input=zip.getInputStream(zip.getEntry("생활경제.db"))){java.nio.file.Files.copy(input,copy,java.nio.file.StandardCopyOption.REPLACE_EXISTING);}assertTrue(StateStore.validSnapshot(copy));}finally{java.nio.file.Files.deleteIfExists(copy);}}
    }
    @Test void nativeNpcFoodAndQuestCategoriesKeepOldTags(){assertEquals(ShopCategory.CROPS,ShopCategory.valueOf("CROPS"));assertEquals(ShopCategory.FOOD,ShopCategory.parse("요리"));assertEquals(ShopCategory.QUESTS,ShopCategory.parse("임무"));}
}
